-- ============================================================
-- S21b: Template section → client_notes category mapping
-- Studios tag individual sections in a consent template with a
-- client_notes category ('allergies'|'medical'|'skin'|'emergency_contact').
-- On submission, matching sections propagate their answers as pinned
-- client_notes rows, feeding the S18 HealthAlertBadge view.
-- ============================================================

-- Mapping lives in a sidecar table (keeps sections JSON backwards-compat)
create table consent_template_note_mappings (
  id              uuid primary key default gen_random_uuid(),
  studio_id       uuid not null references studios(id) on delete cascade,
  template_id     uuid not null references consent_form_templates(id) on delete cascade,
  section_id      text not null,            -- matches the id in template.sections JSON
  note_category   text not null check (note_category in ('allergies', 'medical', 'skin', 'emergency_contact', 'general')),
  note_prefix     text,                     -- optional: prepended to the answer body (e.g. "Self-reported: ")
  is_pinned       boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (template_id, section_id)
);

create index consent_template_note_mappings_template_idx
  on consent_template_note_mappings (template_id);

create trigger consent_template_note_mappings_updated_at
  before update on consent_template_note_mappings
  for each row execute procedure set_updated_at();

alter table consent_template_note_mappings enable row level security;

create policy "consent_template_note_mappings_select"
  on consent_template_note_mappings for select
  using (
    exists (
      select 1 from studio_members sm
      where sm.studio_id = consent_template_note_mappings.studio_id
        and sm.user_id = auth.uid()
        and sm.deactivated_at is null
    )
  );

create policy "consent_template_note_mappings_insert"
  on consent_template_note_mappings for insert
  with check (
    exists (
      select 1 from studio_members sm
      where sm.studio_id = consent_template_note_mappings.studio_id
        and sm.user_id = auth.uid()
        and sm.deactivated_at is null
        and sm.role in ('owner', 'admin')
    )
  );

create policy "consent_template_note_mappings_update"
  on consent_template_note_mappings for update
  using (
    exists (
      select 1 from studio_members sm
