-- ── Propagation trigger on consent_form_submissions ──────────
-- On INSERT: iterate mappings for template_id, extract answer from
-- submission.answers JSONB by section_id, create matching client_notes row.
-- Idempotent via (client_id, category, body_hash) dedupe logic in the trigger.
create or replace function propagate_consent_answers_to_client_notes()
returns trigger
language plpgsql
security definer  -- runs with elevated perms to insert into client_notes
set search_path = public
as $$
declare
  mapping record;
  answer_value text;
  body_text text;
begin
  -- No propagation if submission is not linked to a client
  if new.client_id is null then
    return new;
  end if;

  for mapping in
    select note_category, section_id, note_prefix, is_pinned
    from consent_template_note_mappings
    where template_id = new.template_id
      and studio_id   = new.studio_id
  loop
    -- Extract answer by section_id key (answers JSONB is keyed by section id)
    answer_value := new.answers ->> mapping.section_id;

    -- Skip empty/null answers
    if answer_value is null or length(trim(answer_value)) = 0 then
      continue;
    end if;

    -- Compose note body
    body_text := coalesce(mapping.note_prefix, 'Intake form (' || to_char(new.signed_at, 'YYYY-MM-DD') || '): ') || answer_value;

    -- Insert the note. Dedup by checking for exact body match in past 24h
    -- (prevents re-runs from duplicating if submission is re-inserted).
    if not exists (
      select 1 from client_notes
      where client_id = new.client_id
        and studio_id = new.studio_id
        and category  = mapping.note_category
        and body      = body_text
        and created_at > now() - interval '24 hours'
    ) then
      insert into client_notes (studio_id, client_id, category, body, is_pinned, author_id)
      values (new.studio_id, new.client_id, mapping.note_category, body_text, mapping.is_pinned, null);
    end if;
  end loop;

  return new;
end;
$$;

create trigger consent_submissions_propagate_to_notes
  after insert on consent_form_submissions
  for each row execute function propagate_consent_answers_to_client_notes();

